<script setup lang="ts">
import { computed, onBeforeUnmount, ref, watch } from 'vue'
import { useSimulationStore } from '@/stores/simulation'
import { useAssistantStore } from '@/stores/assistant'
import { actions } from '@/config/robots'
import { executionLabels } from '@/types/assistant'
import { instructionLabel } from '@/simulation/commands'
import RobotViewport from '@/components/RobotViewport.vue'
import AppIcon from '@/components/AppIcon.vue'
const sim = useSimulationStore(), ai = useAssistantStore(), input = ref(''), settings = ref(false)
const viewport = ref<InstanceType<typeof RobotViewport>>()
const quickCommands = computed(() => sim.selectedId === 'quadruped'
  ? ['向前走1秒，然后向左转45度', '坐下，然后站起来', '跳跃', '扫描周围环境', '开始巡检', '停止当前任务']
  : ['挥手，然后举起双臂', '张开手掌，然后抓握', '下蹲，然后站起来', '弯腰抓起箱子', '搬运箱子', '指向目标'])
watch(() => sim.selectedId, robot => {
  ai.cancel(); sim.send({ type: 'perception', command: { type: 'enter', robot } })
  sim.send({ type: 'perception', command: { type: 'settings', values: { mode: 'normal', scanning: false } } })
  ai.feedback = ''; input.value = ''
}, { immediate: true, flush: 'sync' })
onBeforeUnmount(() => { ai.cancel(); sim.send({ type: 'perception', command: { type: 'leave' } }) })
async function submit() { const text = input.value.trim(); if (!text) return; await ai.request(text); if (!ai.rejectedText) input.value = '' }
</script>

<template>
  <div class="assistant-page" :data-ai-status="ai.active?.status ?? ai.history[0]?.status ?? 'idle'" :data-ai-step="ai.active?.step" :data-ai-action="sim.current.action" :data-ai-position="JSON.stringify(sim.current.worldPosition)" :data-ai-heading="sim.current.heading">
    <div class="page-heading"><div><div class="eyebrow">NEXT ROBOTICS / AI CONTROL</div><h1>AI 智能控制<span>.</span></h1><p>说出动作，观察机器人如何一步步执行。</p></div><span class="badge">SIMULATION</span></div>
    <div class="assistant-toolbar"><div class="segmented" aria-label="AI 控制机器人"><button v-for="id in (['quadruped', 'humanoid'] as const)" :key="id" :data-ai-robot="id" :class="{ active: sim.selectedId === id }" :aria-pressed="sim.selectedId === id" @click="sim.select(id)">{{ id === 'quadruped' ? '机器狗 · RV K1' : '人形机器人 · RV H1' }}</button></div><div class="safety-actions"><button class="btn btn-ghost" @click="sim.send({ type: 'pause', value: !sim.snapshot.paused })">{{ sim.snapshot.paused ? '继续仿真' : '暂停仿真' }}</button><button class="btn emergency-btn" @click="sim.send({ type: sim.current.emergency ? 'release' : 'emergency', robot: sim.selectedId })">{{ sim.current.emergency ? '解除急停' : '紧急停止' }}</button></div></div>
    <div class="assistant-main">
      <div class="assistant-scene"><RobotViewport ref="viewport" perception /><div class="scene-readout"><button class="btn btn-ghost" @click="viewport?.focusRobot()">聚焦机器人</button><button class="btn btn-ghost" @click="viewport?.fit()">全场总览</button><span>{{ actions[sim.current.action].label }} · {{ sim.current.heading.toFixed(0) }}°</span><label>移动速度 <input aria-label="AI 移动速度" type="range" min="0" :max="sim.definition.maxSpeed" step="0.1" :value="sim.current.targetSpeed" :disabled="!!ai.active || sim.current.emergency || sim.snapshot.paused" @input="sim.send({ type: 'speed', robot: sim.selectedId, value: +($event.target as HTMLInputElement).value })" /><b class="mono">{{ sim.current.targetSpeed.toFixed(1) }} m/s</b></label></div></div>
      <aside class="assistant-panel panel" aria-label="AI Assistant">
        <header><div><span class="eyebrow">ROBOT ASSISTANT</span><h2>指令控制台</h2></div><button class="icon-btn" aria-label="AI 服务配置" :aria-expanded="settings" @click="settings = !settings"><AppIcon name="settings" /></button></header>
        <div class="assistant-context"><span><i class="dot" />{{ ai.providerName }}</span><span>{{ sim.definition.name }}</span></div>
        <div v-if="settings" class="provider-settings">
          <label class="field">Provider<select v-model="ai.config.provider" aria-label="AI Provider" :disabled="!!ai.busy"><option value="local">本地规则解析</option><option value="proxy">用户配置的安全代理</option></select></label>
          <template v-if="ai.config.provider === 'proxy'"><label class="field">API Base URL<input v-model="ai.config.baseUrl" aria-label="API Base URL" placeholder="https://your-proxy/robot-commands" :disabled="!!ai.busy" /></label><label class="field">API Key · 代理访问令牌<input v-model="ai.config.apiKey" aria-label="API Key" type="password" autocomplete="off" placeholder="仅当前内存保存" :disabled="!!ai.busy" /></label><label class="field">Model<input v-model="ai.config.model" aria-label="AI Model" :disabled="!!ai.busy" /></label><label class="enable-proxy"><input v-model="ai.config.enabled" type="checkbox" :disabled="!!ai.busy" />启用安全代理</label><p>上游密钥由后端保管。代理接入协议见交付文档；停用后立即使用本地规则。</p></template>
          <button class="btn btn-ghost" :disabled="!!ai.busy" @click="ai.request()">{{ ai.busy === 'testing' ? '测试连接中…' : '测试连接' }}</button>
        </div>
        <div class="command-feed" aria-label="指令执行记录" aria-live="polite">
          <div v-if="!ai.history.length" class="assistant-welcome"><AppIcon name="robot" /><h3>你的下一条指令？</h3><p>支持明确的中文动作。用“然后”连接多个步骤，也可加秒数或转向角度。</p><small>例如：让机器狗向前走1秒，然后向左转45度。</small></div>
          <article v-for="run in ai.history" :key="run.id" class="command-run" :data-run-id="run.id" :data-run-status="run.status"><div class="user-message">{{ run.text }}</div><div class="run-meta"><span :class="run.status">{{ executionLabels[run.status] }}</span><small>{{ run.provider }} · {{ run.commands[0]?.robotType === 'quadruped' ? 'RV K1' : 'RV H1' }} · {{ run.createdAt }}</small></div><ol><li v-for="(command, index) in run.commands" :key="index" :class="{ current: index === run.step && run.status === 'running', done: index < run.step }"><span>{{ index < run.step ? '✓' : index + 1 }}</span>{{ instructionLabel(command) }}<small>{{ command.parameters.degrees ? `${command.parameters.degrees}°` : command.action === 'stop' ? '立即' : `${command.duration}s` }}</small></li></ol><p class="run-message">{{ run.message }}<template v-if="run.status === 'running'"> · 第 {{ run.step + 1 }} / {{ run.commands.length }} 步 · {{ run.elapsed.toFixed(1) }}s</template></p></article>
        </div>
        <div v-if="ai.feedback" class="assistant-feedback" :role="ai.rejectedText ? 'alert' : 'status'"><small v-if="ai.rejectedText">{{ ai.rejectedText }}</small>{{ ai.feedback }}</div>
        <div class="command-composer"><div class="quick-commands"><button v-for="text in quickCommands" :key="text" :disabled="!!ai.busy" @click="input = text">{{ text }}</button></div><form @submit.prevent="submit"><label class="sr-only" for="robot-instruction">自然语言机器人指令</label><textarea id="robot-instruction" v-model="input" rows="2" maxlength="240" placeholder="输入机器人指令…" :disabled="!!ai.busy" @keydown.enter.exact.prevent="!$event.isComposing && submit()" /><div class="composer-actions"><span>{{ ai.busy === 'parsing' ? '指令识别中…' : ai.active ? `当前任务 · ${ai.active.step + 1}/${ai.active.commands.length}` : '等待你的指令 · 本地白名单' }}</span><button type="button" class="btn btn-ghost" :disabled="!ai.active && !ai.busy" @click="ai.cancel()">取消任务</button><button class="btn btn-primary" :disabled="!input.trim() || !!ai.busy">发送</button></div></form><button class="clear-history" :disabled="!!ai.active || !!ai.busy || !ai.history.length" @click="sim.send({ type: 'clearAssistant' })">清空会话历史</button></div>
      </aside>
    </div>
    <p class="assistant-note">SIMULATION · 前进/后退按朝向移动，时长决定最大距离，遇实体或场地安全边界提前停止；巡检为避障单程扫描演示。抓取、搬运与指向执行既有机械动作，对象交互与完整任务请进入 MISSIONS 任务中心。历史最多保留 30 条，刷新清空。</p>
  </div>
</template>

<style scoped lang="less">
.page-heading { margin-bottom: 16px; .eyebrow { font-size: 8px; } h1 { margin-top: 7px; span { color: var(--cyan); } } p { font-size: 11px; } }
.assistant-toolbar,.safety-actions { display: flex; align-items: center; gap: 10px; }.assistant-toolbar { justify-content: space-between; margin-bottom: 16px; }.segmented button { font-size: 11px; }.emergency-btn { color: var(--danger); border: 1px solid #ff788a60; background: #ff788a08; }
.assistant-main { display: grid; grid-template-columns: minmax(0,1fr) 380px; gap: 18px; height: clamp(490px,calc(100dvh - 325px),900px); }.assistant-scene { min-width: 0; display: flex; flex-direction: column; gap: 10px; > :deep(.viewport) { min-height: 0; flex: 1; } }.scene-readout { display: flex; flex-wrap: wrap; align-items: center; gap: 8px; font-size: 10px; color: var(--muted); .btn { font-size: 10px; padding: 7px 9px; min-height: 32px; } > span { margin-left: auto; } label { display: flex; width: 100%; align-items: center; gap: 12px; } input { flex: 1; min-width: 60px; accent-color: var(--cyan); } b { font-weight: 400; font-size: 9px; } }
.assistant-panel { display: flex; flex-direction: column; min-height: 0; overflow: hidden; header { padding: 17px 18px 11px; display: flex; align-items: center; justify-content: space-between; .eyebrow { font-size: 8px; } h2 { font-size: 15px; font-weight: 500; margin-top: 6px; } } }.assistant-context { padding: 0 18px 14px; display: flex; gap: 12px; justify-content: space-between; border-bottom: 1px solid var(--border); color: var(--muted); font-size: 9px; .dot { width: 5px; height: 5px; color: var(--success); margin-right: 5px; } }
.command-feed { flex: 1; min-height: 80px; overflow-y: auto; padding: 16px 18px; display: flex; flex-direction: column; gap: 22px; }.assistant-welcome { margin: auto 0; padding: 14px 4px; color: var(--muted); .icon { color: var(--cyan); width: 25px; height: 25px; } h3 { font-size: 16px; color: var(--text); margin: 14px 0 10px; font-weight: 500; } p,small { font-size: 11px; line-height: 1.9; } small { color: var(--faint); display: block; margin-top: 12px; } }.user-message { font-size: 12px; line-height: 1.7; background: #00c8ff0b; padding: 10px 12px; border-radius: 8px 8px 0 8px; overflow-wrap: anywhere; }.run-meta { display: flex; gap: 8px; align-items: center; margin: 12px 0; color: var(--muted); font-size: 10px; small { margin-left: auto; font-size: 8px; } .running,.queued { color: var(--cyan); }.succeeded { color: var(--success); }.failed { color: var(--warning); } }.command-run ol { list-style: none; padding: 0; margin: 0; display: grid; gap: 7px; li { display: flex; align-items: center; gap: 8px; font-size: 10px; color: var(--faint); > span { border: 1px solid var(--border); width: 18px; height: 18px; border-radius: 50%; display: grid; place-items: center; font-size: 8px; } small { margin-left: auto; } &.current { color: var(--cyan); } &.done { color: var(--success); } } }.run-message { font-size: 10px; color: var(--muted); margin-top: 11px; line-height: 1.7; }
.command-composer { border-top: 1px solid var(--border); padding: 13px 16px 10px; }.quick-commands { display: flex; flex-wrap: wrap; gap: 6px; margin-bottom: 11px; button { font-size: 9px; line-height: 1.6; color: var(--muted); background: #ffffff04; padding: 5px 7px; border: 1px solid var(--border); border-radius: 5px; &:hover { color: var(--cyan); border-color: #00c8ff55; } } } textarea { width: 100%; resize: vertical; min-height: 65px; max-height: 130px; border: 1px solid var(--border); border-radius: 7px; background: var(--bg); color: var(--text); padding: 10px; font: inherit; font-size: 12px; line-height: 1.6; }.composer-actions { display: flex; gap: 6px; align-items: center; margin-top: 8px; > span { flex: 1; font-size: 9px; color: var(--muted); } .btn { font-size: 10px; padding: 7px 10px; min-height: 32px; } }.clear-history { display: block; margin: 9px auto 0; font-size: 9px; color: var(--faint); background: transparent; }.assistant-feedback { font-size: 11px; padding: 10px 16px; line-height: 1.8; color: var(--warning); background: #ffba6709; overflow-wrap: anywhere; small { display: block; color: var(--muted); } }.provider-settings { padding: 14px 18px; border-bottom: 1px solid var(--border); display: grid; gap: 12px; overflow-y: auto; max-height: 320px; flex-shrink: 0; .field { font-size: 10px; gap: 6px; } input,select { font-size: 11px; width: 100%; } .enable-proxy { display: flex; gap: 7px; align-items: center; font-size: 11px; input { width: auto; } } p { font-size: 9px; line-height: 1.7; color: var(--muted); } }.assistant-note { font-size: 9px; color: var(--faint); line-height: 1.8; margin-top: 16px; }.sr-only { position: absolute; width: 1px; height: 1px; overflow: hidden; clip-path: inset(50%); }
@media(min-width:1600px) { .assistant-main { grid-template-columns: minmax(0,1fr) 420px; } }
@media(max-width:900px) { .assistant-main { grid-template-columns: 1fr; height: auto; }.assistant-scene { height: 460px; }.assistant-panel { height: 650px; }.assistant-toolbar { flex-wrap: wrap; }.safety-actions { margin-left: auto; }.command-feed { min-height: 100px; } }
@media(max-width:550px) { .assistant-scene { height: 410px; }.assistant-toolbar .btn,.segmented button { font-size: 10px; min-height: 38px; }.assistant-panel { height: 680px; }.assistant-note { font-size: 8px; }.quick-commands button { min-height: 32px; }.composer-actions .btn { min-height: 38px; } }
</style>
